 for(int depth=0;depth<8;++depth){MenuLayerState state;check(!state.active(),"idle permits ordinary multi-monitor topmost maintenance");check(state.begin()&&state.active(),"guard starts before foreground/menu API calls");check(!state.begin(),"recursive tracking cannot own the same guard");for(int i=0;i<depth;++i){state.enter();check(state.active(),"all nested menu loops suspend foreground and periodic correction");}for(int i=0;i<depth;++i){state.exit();check(state.active(),"WM_EXITMENULOOP cannot restore before TrackPopupMenu returns");}state.finish();check(!state.active()&&!state.tracking&&!state.loops,"selection, ESC, outside cancellation, failure and exception cleanup release guard");state.exit();check(!state.active(),"unpaired exit is harmless");}
